// Normalizes the caller's inputs and emits the curated catalog for the
// rest of the pipeline. Nothing here reads the request to decide what a
// scheme says: the catalog is a fixed constant, so a crafted request can
// never introduce scheme content (see docs/api-contracts.md).

const input = $input.first() ? $input.first().json : {};

const text = (v) =>
  typeof v === "string" && v.trim() !== "" ? v.trim() : null;

// areaAcres arrives as a string when the API workflow stringifies inputs;
// anything non-numeric stays null so the area criterion says
// "cannot check" rather than silently reading as 0 acres.
const num = (v) => {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string" && v.trim() !== "" && Number.isFinite(Number(v))) {
    return Number(v);
  }
  return null;
};

// crops may arrive as a JSON string (Execute Workflow stringifies inputs),
// as a real array, or as a comma-separated list. Nothing is invented if
// none of those parse: the farmer simply has no crops recorded.
const parseCrops = (v) => {
  let raw = v;
  if (typeof raw === "string") {
    const s = raw.trim();
    if (s === "") return [];
    if (s.charAt(0) === "[") {
      try {
        raw = JSON.parse(s);
      } catch (e) {
        raw = s.split(",");
      }
    } else {
      raw = s.split(",");
    }
  }
  if (!Array.isArray(raw)) return [];
  const out = [];
  for (const item of raw) {
    const name =
      typeof item === "string"
        ? item
        : item && typeof item === "object"
          ? item.cropName || item.crop_name || item.name
          : null;
    const cleaned = text(name);
    if (cleaned) out.push(cleaned);
  }
  return out;
};

return [
  {
    json: {
      askedState: text(input.state),
      askedDistrict: text(input.district),
      areaAcres: num(input.areaAcres),
      crops: parseCrops(input.crops),
      locale: text(input.locale) || "en",
      catalogVersion: CATALOG_VERSION,
      catalogCount: CATALOG.length,
      catalog: CATALOG
    }
  }
];

// Decides which schemes are even in scope for this farm.
//
// Central schemes apply everywhere. A state scheme applies only to its own
// states, and only once the farm's free-text state has been resolved to a
// canonical name. A farm with no saved state is NOT treated as "no state
// schemes apply" — it is treated as "state schemes could not be
// considered", and the flag below makes the UI say exactly that.
//
// Resolution is exact-or-nothing, the same discipline as the Market
// Agent's district matching: lowercase, letters only, then compare. That
// handles "tamilnadu" / "Tamil Nadu" / "TAMIL NADU" without ever guessing
// between two different states.

const STATES = [
  "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh",
  "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka",
  "Kerala", "Madhya Pradesh", "Maharashtra", "Manipur", "Meghalaya",
  "Mizoram", "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim",
  "Tamil Nadu", "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand",
  "West Bengal", "Andaman and Nicobar Islands", "Chandigarh",
  "Dadra and Nagar Haveli and Daman and Diu", "Delhi", "Jammu and Kashmir",
  "Ladakh", "Lakshadweep", "Puducherry"
];

// Names that are not spelling variants but different names entirely.
const STATE_ALIASES = {
  orissa: "Odisha",
  keralam: "Kerala",
  pondicherry: "Puducherry",
  uttaranchal: "Uttarakhand",
  newdelhi: "Delhi",
  nctofdelhi: "Delhi",
  jammukashmir: "Jammu and Kashmir"
};

const plain = (v) =>
  String(v == null ? "" : v).toLowerCase().replace(/[^a-z]/g, "");

const resolveState = (asked) => {
  const key = plain(asked);
  if (!key) return null;
  if (STATE_ALIASES[key]) return STATE_ALIASES[key];
  const hits = STATES.filter((s) => plain(s) === key);
  return hits.length === 1 ? hits[0] : null;
};

const data = $input.first().json;
const stateResolved = resolveState(data.askedState);

const inScope = [];
for (const scheme of data.catalog) {
  if (scheme.level === "central") {
    inScope.push(scheme);
    continue;
  }
  // A state scheme needs a resolved state to be in scope at all. Without
  // one it is left out of the results and counted below, so the farmer is
  // told how many schemes could not be considered rather than being shown
  // a shorter list with no explanation.
  if (stateResolved && scheme.states.indexOf(stateResolved) !== -1) {
    inScope.push(scheme);
  }
}

const stateSchemesSkipped = stateResolved
  ? 0
  : data.catalog.filter((s) => s.level === "state").length;

return [
  {
    json: {
      askedState: data.askedState,
      askedDistrict: data.askedDistrict,
      stateResolved,
      stateSchemesSkipped,
      areaAcres: data.areaAcres,
      crops: data.crops,
      locale: data.locale,
      catalogVersion: data.catalogVersion,
      totalSchemes: data.catalog.length,
      schemes: inScope
    }
  }
];

// Evaluates each in-scope scheme's criteria against what the farmer has
// actually recorded, and sorts it into one of three groups.
//
// THIS DELIBERATELY CANNOT PRODUCE AN "ELIGIBLE" VERDICT. Every catalog
// entry carries at least one criterion of kind "manual" — something only
// the farmer or the issuing office can confirm (land records, income-tax
// status, an enrolment window). Those always evaluate to "cannot_check"
// and are always returned, so the strongest statement the UI can make is
// "this matches what you have told us", never "you qualify". Getting that
// wrong in either direction is costly: a false yes sends a farmer on a
// wasted trip, a false no costs them a benefit they were entitled to.
//
// Groups:
//   other       at least one criterion is contradicted by recorded data
//   matched     nothing contradicted, and at least one criterion passed
//   needs_check nothing contradicted, but nothing could be checked either

const STALENESS_DAYS = 180;

const data = $input.first().json;
const areaAcres = data.areaAcres;
const crops = Array.isArray(data.crops) ? data.crops : [];
const cropsLower = crops.map((c) => String(c).toLowerCase());

const evaluateCriterion = (criterion, scheme) => {
  const kind = criterion.kind;

  if (kind === "farm_record") {
    return { status: "matched", params: null };
  }

  if (kind === "land_area_recorded") {
    return {
      status: areaAcres === null ? "cannot_check" : "matched",
      params: areaAcres === null ? null : { acres: areaAcres }
    };
  }

  if (kind === "max_area_acres") {
    const limit = criterion.params ? criterion.params.acres : null;
    if (areaAcres === null || limit == null) {
      return { status: "cannot_check", params: { acres: limit } };
    }
    return {
      status: areaAcres <= limit ? "matched" : "not_matched",
      params: { acres: limit }
    };
  }

  if (kind === "state_match") {
    if (!data.stateResolved) return { status: "cannot_check", params: null };
    return {
      status: scheme.states.indexOf(data.stateResolved) !== -1 ? "matched" : "not_matched",
      params: { state: data.stateResolved }
    };
  }

  if (kind === "crop_recorded") {
    return { status: crops.length > 0 ? "matched" : "not_matched", params: null };
  }

  if (kind === "crop_in") {
    const wanted = criterion.params && Array.isArray(criterion.params.crops)
      ? criterion.params.crops
      : [];
    // No recorded crop is not the same as a wrong crop: the first is
    // unknown, the second is a genuine mismatch.
    if (crops.length === 0) return { status: "cannot_check", params: { crops: wanted } };
    const hit = wanted.some((w) => cropsLower.indexOf(String(w).toLowerCase()) !== -1);
    return { status: hit ? "matched" : "not_matched", params: { crops: wanted } };
  }

  // "manual" and anything unrecognised. An unknown kind must never count
  // as a pass, so it degrades to the same "farmer must confirm" state.
  return { status: "cannot_check", params: null };
};

const daysSince = (iso) => {
  if (typeof iso !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return null;
  const then = Date.parse(iso + "T00:00:00Z");
  if (Number.isNaN(then)) return null;
  return Math.floor((Date.now() - then) / 86400000);
};

// A malformed entry is dropped rather than half-rendered — a scheme card
// with no name or no source link is worse than one fewer scheme.
const isUsable = (s) =>
  s &&
  typeof s === "object" &&
  typeof s.id === "string" && s.id.trim() !== "" &&
  typeof s.name === "string" && s.name.trim() !== "" &&
  (s.level === "central" || s.level === "state") &&
  Array.isArray(s.states) &&
  typeof s.sourceUrl === "string" && /^https:\/\//.test(s.sourceUrl) &&
  typeof s.sourceName === "string" && s.sourceName.trim() !== "" &&
  Array.isArray(s.criteria) && s.criteria.length > 0;

const matches = [];
let oldestVerified = null;

for (const scheme of data.schemes) {
  if (!isUsable(scheme)) continue;

  const criteria = [];
  for (const c of scheme.criteria) {
    if (!c || typeof c.key !== "string" || typeof c.kind !== "string") continue;
    const result = evaluateCriterion(c, scheme);
    criteria.push({ key: c.key, status: result.status, params: result.params });
  }
  if (criteria.length === 0) continue;

  const notMatched = criteria.filter((c) => c.status === "not_matched").length;
  const matchedCount = criteria.filter((c) => c.status === "matched").length;
  const cannotCheck = criteria.filter((c) => c.status === "cannot_check").length;

  // Invariant the contract depends on: if a scheme is shown at all, the
  // farmer is shown something they still have to verify themselves.
  if (cannotCheck === 0) continue;

  const group = notMatched > 0 ? "other" : matchedCount > 0 ? "matched" : "needs_check";

  const age = daysSince(scheme.lastVerifiedOn);
  if (age !== null && (oldestVerified === null || scheme.lastVerifiedOn < oldestVerified)) {
    oldestVerified = scheme.lastVerifiedOn;
  }

  matches.push({
    scheme: {
      id: scheme.id,
      name: scheme.name,
      level: scheme.level,
      states: scheme.states,
      purpose: scheme.purpose || null,
      benefit: scheme.benefit || null,
      appliesToCrops: Array.isArray(scheme.appliesToCrops) ? scheme.appliesToCrops : [],
      sourceName: scheme.sourceName,
      sourceUrl: scheme.sourceUrl,
      lastVerifiedOn: typeof scheme.lastVerifiedOn === "string" ? scheme.lastVerifiedOn : null
    },
    group,
    criteria,
    stale: age === null ? true : age > STALENESS_DAYS
  });
}

return [
  {
    json: {
      askedState: data.askedState,
      askedDistrict: data.askedDistrict,
      stateResolved: data.stateResolved,
      stateSchemesSkipped: data.stateSchemesSkipped,
      locale: data.locale,
      catalogVersion: data.catalogVersion,
      totalSchemes: data.totalSchemes,
      catalogVerifiedOn: oldestVerified,
      matches
    }
  }
];

// Wraps the evaluated matches in the DataResult contract
// (packages/shared-types). asOf is when this request ran;
// catalogVerifiedOn is when a human last checked the oldest entry in the
// catalog. They are separate on purpose — "checked just now" and
// "verified six months ago" are different facts, and collapsing them
// would overstate how current the scheme information is.

const SOURCE = "agri-one-curated-scheme-catalog";

const data = $input.first().json;
const matches = Array.isArray(data.matches) ? data.matches : [];

// An in-scope catalog that evaluates to nothing renderable is reported as
// unavailable rather than as an empty list, so the farmer is never left
// looking at a blank page wondering whether it loaded.
if (matches.length === 0) {
  return [
    {
      json: {
        status: "unavailable",
        reason: "No government schemes could be listed for this farm right now."
      }
    }
  ];
}

return [
  {
    json: {
      status: "ok",
      asOf: new Date().toISOString(),
      source: SOURCE,
      data: {
        state: data.stateResolved,
        district: data.askedDistrict,
        askedState: data.askedState,
        stateSchemesSkipped: data.stateSchemesSkipped,
        totalSchemes: data.totalSchemes,
        catalogVersion: data.catalogVersion,
        catalogVerifiedOn: data.catalogVerifiedOn,
        matches
      }
    }
  }
];

// The curated catalog is empty or unreadable, so there is nothing
// truthful to show. The farmer gets a plain message; the detail goes to
// the n8n execution log so the failure stays diagnosable without leaking
// internals into the UI.

const data = $input.first() ? $input.first().json : {};
console.log(
  "Scheme catalog unusable:",
  JSON.stringify({ catalogVersion: data.catalogVersion, catalogCount: data.catalogCount })
);

return [
  {
    json: {
      status: "unavailable",
      reason: "The government scheme list is not available right now. Please try again."
    }
  }
];
